# WARNING: Under review - generated by LLM.

"""Week 4, Day 1: the validated agent loop.

The loop turns model text into one bounded, schema-checked action or final
response.  It stops by budget, returns invalid actions to the model, and
guards against repeated identical actions.  Later days add durable event
recording (Day 3 sessions), token-aware context management (Day 5), and
cancellation/steering (Day 6); this file keeps only the validated core so
each day's feature is reviewable on its own.
"""

import json
from collections.abc import Callable
from dataclasses import dataclass
from typing import Any

from .generation import Generate, Message, initial_messages
from .protocol import (
    AgentError,
    AgentAction,
    FinalAction,
    build_system_prompt,
    parse_action,
)
from .session import SessionLog


@dataclass(frozen=True)
class AgentLimits:
    """Budgets that guarantee the loop eventually stops."""

    max_steps: int = 8
    max_context_chars: int = 48_000
    max_invalid_actions: int = 3
    max_identical_actions: int = 2

    def __post_init__(self) -> None:
        if (
            min(
                self.max_steps,
                self.max_context_chars,
                self.max_invalid_actions,
                self.max_identical_actions,
            )
            <= 0
        ):
            raise ValueError("agent limits must be positive")


@dataclass(frozen=True)
class AgentEvent:
    """One auditable model/action/tool interaction."""

    step: int
    response: str
    action: AgentAction | None
    result: str | None


@dataclass(frozen=True)
class AgentRun:
    """One bounded run; ``completed`` means the model returned a valid final."""

    completed: bool
    reason: str
    final: str | None
    events: tuple[AgentEvent, ...]
    modified_files: tuple[str, ...] = ()
    session_id: str | None = None


def _append_tool_result(
    messages: list[Message], response: str, result: str
) -> list[Message]:
    """Append one assistant response and its tool observation."""

    return [
        *messages,
        {"role": "assistant", "content": response},
        {"role": "user", "content": f"Tool result:\n{result}"},
    ]


def run_agent(
    task: str | None,
    generate: Generate,
    workspace: Any,
    limits: AgentLimits | None = None,
    on_event: Callable[[AgentEvent], None] | None = None,
    *,
    session: SessionLog | None = None,
) -> AgentRun:
    """Run a bounded validated loop over one task.

    ``workspace`` must expose ``available_tools`` (a frozenset of tool names),
    ``execute(action)`` (returning a result string), and ``modified_files``
    (an iterable of paths).  When ``session`` is provided (Day 3), every
    interaction is recorded as an immutable event in the durable event tree.
    """

    limits = limits or AgentLimits()
    if task is None or not task.strip():
        raise ValueError("task must not be empty")
    system_prompt = build_system_prompt(workspace)
    messages = initial_messages(task, system_prompt)
    events: list[AgentEvent] = []
    invalid_actions = 0
    previous_signature: str | None = None
    identical_actions = 0
    if session is not None:
        session.append("user_message", content=task)
        session.append("run_started")

    def finish(completed: bool, reason: str, final: str | None = None) -> AgentRun:
        if session is not None:
            session.append(
                "run_finished", completed=completed, reason=reason, final=final
            )
        return AgentRun(
            completed,
            reason,
            final,
            tuple(events),
            tuple(sorted(workspace.modified_files)),
            session_id=session.session_id if session is not None else None,
        )

    for step in range(1, limits.max_steps + 1):
        if (
            sum(len(message["content"]) for message in messages)
            > limits.max_context_chars
        ):
            return finish(False, "context_limit")

        response = generate(messages)
        try:
            action = parse_action(response, workspace.available_tools)
        except AgentError as error:
            invalid_actions += 1
            previous_signature = None
            identical_actions = 0
            result = f"error: {error}"
            event = AgentEvent(step, response, None, result)
            events.append(event)
            if on_event is not None:
                on_event(event)
            if session is not None:
                session.append(
                    "tool_result",
                    tool_call_id=None,
                    tool=None,
                    is_error=True,
                    content=result,
                )
            if invalid_actions >= limits.max_invalid_actions:
                return finish(False, "invalid_action_limit")
            messages = _append_tool_result(messages, response, result)
            continue

        if isinstance(action, FinalAction):
            event = AgentEvent(step, response, action, None)
            events.append(event)
            if on_event is not None:
                on_event(event)
            return finish(True, "completed", action.final)

        signature = json.dumps(
            {"tool": action.tool, **action.arguments}, sort_keys=True
        )
        if signature == previous_signature:
            identical_actions += 1
        else:
            previous_signature = signature
            identical_actions = 1
        if identical_actions > limits.max_identical_actions:
            result = "error: identical action loop detected"
            event = AgentEvent(step, response, action, result)
            events.append(event)
            if on_event is not None:
                on_event(event)
            if session is not None:
                session.append(
                    "tool_result",
                    tool_call_id=None,
                    tool=action.tool,
                    is_error=True,
                    content=result,
                )
            return finish(False, "repeated_action_limit")

        tool_call = None
        if session is not None:
            tool_call = session.append(
                "tool_call", tool=action.tool, arguments=action.arguments
            )
        result = workspace.execute(
            action, tool_call_id=tool_call.id if tool_call is not None else None
        )
        if session is not None:
            session.append(
                "tool_result",
                tool_call_id=tool_call.id,
                tool=action.tool,
                arguments=action.arguments,
                is_error=result.startswith("error:"),
                content=result,
            )
        event = AgentEvent(step, response, action, result)
        events.append(event)
        if on_event is not None:
            on_event(event)
        messages = _append_tool_result(messages, response, result)

    return finish(False, "step_limit")
